// src/model/nullability-transition.ts
var check4 = createValidator().compile(nullability_transition_schema_default);
function document2(input, version) {
  const copied = copyJson(input);
  if (!validateDocument(copied).valid || copied.umf !== version)
    throw new UmfError("NULLABILITY_TRANSITION_INPUT", "Expected valid " + version + " envelope");
  return copied;
}
function finish(value) {
  const copied = copyJson(value);
  if (!check4(copied))
    throw new UmfError("NULLABILITY_TRANSITION_RESULT", JSON.stringify(check4.errors));
  return copied;
}
function upgradeNullabilityEnvelope(input) {
  const source = document2(input, "0.2.0"), target = copyJson(source);
  const residuals = [];
  target.umf = "0.3.0";
  target.modules.forEach((module, mi) => module.elements.forEach((element, ei) => {
    if (Object.hasOwn(element, "nullability")) {
      residuals.push({ path: `/modules/${mi}/elements/${ei}/nullability`, value: copyJson(element.nullability), reason: "Legacy nullability is opaque; no availability assertion inferred" });
      delete element.nullability;
    }
  }));
  return finish({ operation: "upgrade-nullability-envelope", version: "1.0.0", source, target, residuals });
}
function canonical2(value) {
  if (Array.isArray(value))
    return "[" + value.map(canonical2).join(",") + "]";
  if (value !== null && typeof value === "object")
    return "{" + Object.keys(value).sort().map((key) => JSON.stringify(key) + ":" + canonical2(value[key])).join(",") + "}";
  return JSON.stringify(value);
}
function rollbackNullabilityEnvelope(input, current) {
  const receipt = copyJson(input);
  if (!check4(receipt) || receipt.operation !== "upgrade-nullability-envelope")
    throw new UmfError("NULLABILITY_TRANSITION_RECEIPT", "Invalid upgrade receipt");
  const expected = upgradeNullabilityEnvelope(receipt.source);
  if (canonical2(copyJson(expected)) !== canonical2(copyJson(receipt)))
    throw new UmfError("NULLABILITY_TRANSITION_RECEIPT", "Receipt conflicts with its retained source");
  const source = document2(current, "0.3.0");
  if (source.id !== receipt.target.id)
    throw new UmfError("NULLABILITY_TRANSITION_ID", "Current document identity differs from upgrade");
  return finish({ operation: "rollback-nullability-envelope", version: "1.0.0", source, target: receipt.source, receipt, reason: "Original envelope restored; all subsequent content retained in source, not applied to legacy target" });
}
