      const orderId = Math.max(0, ...metadata["sort-orders"].map((row) => row["order-id"])) + 1;
      metadata["sort-orders"].push({ "order-id": orderId, fields });
      metadata["default-sort-order-id"] = orderId;
      candidate = JSON.stringify(metadata) + `
`;
