// src/adapters/delta/parquet-checkpoint.ts
function reconcileDeltaParquetCheckpoint(checkpoint, commits, spec, sidecars = []) {
  const r = { status: "blocked", complete: false, spec, checkpoint: copyJson(checkpoint), sources: copyJson(commits), sidecars: copyJson(sidecars), diagnostics: [] };
  const issue = (message) => r.diagnostics.push({ code: "DELTA_PARQUET_CHECKPOINT", path: "", severity: "error", message });
  if (spec !== "v1" && spec !== "v2") {
    issue("Expected v1 or v2 checkpoint spec");
    return r;
  }
  if (spec === "v1" && sidecars.length) {
    issue("V1 checkpoints cannot use supplied sidecars");
    return r;
  }
  try {
    r.projection = projectDeltaParquetActions(r.checkpoint.source);
    r.diagnostics.push(...r.projection.diagnostics.map((d) => ({ ...d, path: "/projection" + d.path })));
    if (r.projection.status !== "projected")
      return r;
    const derived = { version: r.checkpoint.version, source: r.projection.log };
    r.recovery = spec === "v1" ? reconcileDeltaCheckpoint(derived, r.sources, "v1") : reconcileDeltaCheckpointSidecars(derived, r.sources, r.sidecars);
    r.diagnostics.push(...r.recovery.diagnostics.map((d) => ({ ...d, path: "/recovery" + d.path })));
    r.status = r.recovery.status;
  } catch (e) {
    issue(e.message);
  }
  return r;
}
